from pathlib import Path
ROOT=Path.cwd()
FILES={
    'server/src/modules/module-standards/standard-directive.cache.ts': "/**\n * Runtime prompt projection of the public System Workflow Rule Registry.\n * The cache never owns public rule text or thresholds; it only selects active rules\n * for a scene and renders their registry directives.\n */\nimport { createHash } from 'node:crypto';\nimport { standardScene } from '../../routing/scenario-taxonomy';\nimport {\n  SYSTEM_WORKFLOW_RULESET_VERSION,\n  activeSystemWorkflowRules,\n} from './system-workflow-rules.registry';\nimport type { SystemWorkflowRule } from './system-workflow-rule.types';\n\nclass StandardDirectiveCacheClass {\n  private rebuiltAt = 0;\n  private rules: SystemWorkflowRule[] = [];\n\n  rebuild(rules: readonly SystemWorkflowRule[] = activeSystemWorkflowRules()): void {\n    this.rules = structuredClone([...rules]);\n    this.rebuiltAt = Date.now();\n  }\n\n  private format(rule: SystemWorkflowRule, scene: string): string {\n    const lines = [`【系统规则 ${rule.id} · ${rule.level} · ${rule.name}】${rule.summary}`];\n    for (const detail of rule.details ?? []) lines.push(`- ${detail}`);\n    const directives = rule.directives;\n    if (directives) {\n      if (['review'].includes(scene) && directives.review) lines.push(`评审：${directives.review}`);\n      else if (['polish'].includes(scene) && directives.repair) lines.push(`修复：${directives.repair}`);\n      else if (directives.generation) lines.push(`生成：${directives.generation}`);\n      if (directives.save && ['writing', 'polish', 'review'].includes(scene)) lines.push(`保存：${directives.save}`);\n    }\n    if (rule.evidencePolicy && ['review', 'polish'].includes(scene)) lines.push(`证据：${rule.evidencePolicy}`);\n    return lines.join('\\n');\n  }\n\n  private rulesFor(scenario?: string | null, stepKey?: string | null): SystemWorkflowRule[] {\n    const scene = standardScene(scenario, stepKey);\n    return this.rules.filter((rule) =>\n      rule.status === 'active'\n      && rule.consumers.includes('prompt')\n      && (rule.scenarios.includes('*') || rule.scenarios.includes(scene)),\n    );\n  }\n\n  get(scenario?: string | null, stepKey?: string | null): string {\n    const scene = standardScene(scenario, stepKey);\n    return this.rulesFor(scenario, stepKey).map((rule) => this.format(rule, scene)).join('\\n\\n');\n  }\n\n  getRebuiltAt(): number { return this.rebuiltAt; }\n  getRulesetVersion(): number { return SYSTEM_WORKFLOW_RULESET_VERSION; }\n  getRulesetDigest(): string {\n    const canonical = this.rules\n      .filter((rule) => rule.status === 'active')\n      .map((rule) => ({\n        id: rule.id, level: rule.level, blocking: rule.blocking, scenarios: [...rule.scenarios],\n        summary: rule.summary, details: [...(rule.details ?? [])], evidencePolicy: rule.evidencePolicy ?? null,\n        parameterRefs: [...(rule.parameterRefs ?? [])], dependencies: [...(rule.dependencies ?? [])],\n        directives: rule.directives ?? null,\n      }))\n      .sort((a, b) => a.id.localeCompare(b.id));\n    return createHash('sha256').update(JSON.stringify(canonical)).digest('hex');\n  }\n\n  snapshot(scenario: string, enabled = true, stepKey?: string | null) {\n    const selected = enabled ? this.rulesFor(scenario, stepKey) : [];\n    const directive = enabled ? this.get(scenario, stepKey) : '';\n    return {\n      enabled,\n      available: !!directive,\n      rulesetVersion: SYSTEM_WORKFLOW_RULESET_VERSION,\n      registryDigest: this.getRulesetDigest(),\n      digest: createHash('sha256')\n        .update(`${SYSTEM_WORKFLOW_RULESET_VERSION}\\n${directive}`)\n        .digest('hex'),\n      ruleIds: selected.map((rule) => rule.id),\n      modules: selected.map((rule) => ({\n        key: rule.id,\n        version: SYSTEM_WORKFLOW_RULESET_VERSION,\n        baseline: SYSTEM_WORKFLOW_RULESET_VERSION,\n      })),\n    };\n  }\n\n  clear(): void {\n    this.rules = [];\n    this.rebuiltAt = 0;\n  }\n}\n\nexport const standardDirectiveCache = new StandardDirectiveCacheClass();\n",
    'server/src/chain/source-fact-consistency.ts': "/**\n * Generic deterministic consistency for already-identified story facts.\n * Public rule owner: CTX-005.\n *\n * This layer never guesses story-mechanic identity from nouns. Callers must supply\n * a stable identity (fact id / entity+field / deadline id). Free-form, ambiguous\n * claims belong to the semantic Gate.\n */\nexport type StructuredFactKind = 'number' | 'duration_hours' | 'deadline' | 'location' | 'state';\n\nexport interface StructuredFactClaim {\n  identity: string;\n  kind: StructuredFactKind;\n  value: string | number;\n  source: string;\n  unit?: string;\n  certainty?: 'explicit' | 'derived';\n}\n\nexport interface StructuredFactConflict {\n  ruleId: 'CTX-005';\n  identity: string;\n  kind: StructuredFactKind;\n  claims: StructuredFactClaim[];\n  message: string;\n}\n\nconst text = (value: string | number) => String(value).trim().replace(/\\s+/g, ' ');\nconst identity = (value: string) => value.trim().toLowerCase().replace(/\\s+/g, ' ');\nconst unit = (value?: string) => String(value || '').trim().toLowerCase();\n\nfunction comparableValue(claim: StructuredFactClaim): string | number | null {\n  if (claim.kind === 'number' || claim.kind === 'duration_hours') {\n    const parsed = typeof claim.value === 'number' ? claim.value : Number(text(claim.value));\n    return Number.isFinite(parsed) ? parsed : null;\n  }\n  const normalized = text(claim.value);\n  return normalized ? normalized : null;\n}\n\nfunction conflictInGroup(claims: StructuredFactClaim[]): boolean {\n  const values = claims.map(comparableValue);\n  if (values.some((value) => value === null)) return false;\n  if (claims[0].kind === 'number') {\n    const units = new Set(claims.map((claim) => unit(claim.unit)));\n    if (units.size > 1) return false;\n  }\n  return new Set(values.map((value) => String(value))).size > 1;\n}\n\nexport function detectStructuredFactConflicts(claims: readonly StructuredFactClaim[]): StructuredFactConflict[] {\n  const groups = new Map<string, StructuredFactClaim[]>();\n  for (const claim of claims) {\n    const factIdentity = identity(claim.identity);\n    if (!factIdentity || !claim.source.trim()) continue;\n    const key = `${factIdentity}\\u0000${claim.kind}`;\n    const group = groups.get(key) ?? [];\n    group.push({ ...claim, identity: factIdentity, source: claim.source.trim() });\n    groups.set(key, group);\n  }\n\n  const conflicts: StructuredFactConflict[] = [];\n  for (const group of groups.values()) {\n    if (group.length < 2 || !conflictInGroup(group)) continue;\n    conflicts.push({\n      ruleId: 'CTX-005',\n      identity: group[0].identity,\n      kind: group[0].kind,\n      claims: group,\n      message: `同一事实“${group[0].identity}”存在可确定验证的互斥值：${group.map((claim) => `${claim.source}=${text(claim.value)}${claim.unit ? ` ${claim.unit}` : ''}`).join('；')}。`,\n    });\n  }\n  return conflicts;\n}\n",
    'server/shared/src/system-workflow-rule.types.ts': "export type SystemWorkflowRuleLevel = 'P0' | 'P1' | 'P2' | 'P3';\nexport type SystemWorkflowRuleStatus = 'active' | 'deprecated' | 'replaced';\nexport type SystemWorkflowRuleCategory =\n  | 'governance'\n  | 'authority'\n  | 'architecture'\n  | 'context'\n  | 'generation'\n  | 'quality'\n  | 'repair'\n  | 'workflow'\n  | 'platform'\n  | 'learning';\n\nexport type SystemWorkflowRuleConsumer =\n  | 'prompt'\n  | 'deterministic_gate'\n  | 'semantic_gate'\n  | 'repair'\n  | 'retry'\n  | 'persistence'\n  | 'learning'\n  | 'api'\n  | 'ui'\n  | 'test';\n\nexport interface SystemWorkflowRuleClause {\n  id: string;\n  label: string;\n  text: string;\n}\n\nexport interface SystemWorkflowRuleDirectives {\n  generation?: string;\n  review?: string;\n  repair?: string;\n  save?: string;\n}\n\nexport interface SystemWorkflowRule {\n  id: string;\n  name: string;\n  category: SystemWorkflowRuleCategory;\n  level: SystemWorkflowRuleLevel;\n  status: SystemWorkflowRuleStatus;\n  summary: string;\n  /** Stable detailed clauses belonging to this Rule ID; not independent rules. */\n  details?: readonly string[];\n  /** Structured sub-criteria owned by this Rule ID (for renderers/validators). */\n  clauses?: readonly SystemWorkflowRuleClause[];\n  /** Named public contract fragments owned by this Rule ID; callers may render but not redefine them. */\n  contracts?: Readonly<Record<string, string>>;\n  blocking: boolean;\n  /** `*` means all standard scenes. */\n  scenarios: readonly string[];\n  consumers: readonly SystemWorkflowRuleConsumer[];\n  evidencePolicy?: string;\n  parameterRefs?: readonly string[];\n  dependencies?: readonly string[];\n  implementationRefs: readonly string[];\n  testRefs?: readonly string[];\n  directives?: SystemWorkflowRuleDirectives;\n  replacedBy?: string;\n}\n",
    'server/src/chain/source-rule-consistency.spec.ts': "import { describe, expect, it } from 'vitest';\nimport { describeWorldSourceCandidate } from './source-rule-consistency';\n\ndescribe('generic world source validation', () => {\n  it('rejects malformed/empty world records without encoding a particular story mechanic', () => {\n    expect(describeWorldSourceCandidate({ error: '生成失败', rules: [] }, '甲'))\n      .toContain('世界观rules必须包含至少一条非空因果规则；具体数量由本作品结构需要决定，不设公共固定配额');\n  });\n\n  it('does not impose a universal 2-3 world-rule quota', () => {\n    expect(describeWorldSourceCandidate({\n      era: '任意时代', storyPremise: '甲面对一个需要遵守的核心规则', atmosphere: '自定', endingDirection: '完成本故事收束',\n      rules: ['唯一必要的核心因果规则'], locations: ['地点A'],\n    }, '甲')).toEqual([]);\n  });\n\n  it('accepts a substantive world candidate for arbitrary genres', () => {\n    expect(describeWorldSourceCandidate({\n      era: '当代',\n      storyPremise: '甲在新的现实压力下寻找解决办法',\n      atmosphere: '克制',\n      endingDirection: '完成核心选择并承担后果',\n      rules: ['公开规则一', '公开规则二'],\n      locations: ['地点A'],\n    }, '甲')).toEqual([]);\n  });\n\n  it('keeps protagonist anchoring as structure validation', () => {\n    expect(describeWorldSourceCandidate({\n      era: '当代', storyPremise: '乙的故事', atmosphere: '平静', endingDirection: '收束',\n      rules: ['规则一', '规则二'], locations: ['地点A'],\n    }, '甲')).toContain('世界观storyPremise未保留主角“甲”');\n  });\n});\n",
    'DEVELOPMENT_GOVERNANCE.md': '# 开发治理规范\n\n本文件只约束 `h-huan/novel` 的开发、修改、测试、迁移与交付纪律；**不定义小说业务规则**。小说业务规则唯一入口是 `QUALITY_EXECUTION.md`。\n\n## 1. 不做孤立补丁\n\n发现问题后检查所有同类入口和数据流：写入路径、读取路径、Gate、页面、恢复与回滚。修复顺序：检查现有能力 → 找唯一责任方 → 合并重复实现 → 删除/停用旧流程 → 必要时才新增。\n\n## 2. “代码存在”不等于完成\n\n完整链至少证明：真实持久化 → 权威数据更新 → 派生状态/摘要/索引同步 → 后续读取最新值 → 一致性/质量检查 → UI/报告可观察 → 错误/回滚/恢复正确。\n\n## 3. 不积累平行实现和历史文档\n\n禁止为一个问题新增第二套 Contract、Gate、Context、标准文档而旧实现继续运行。历史由 Git、数据库审计、CI 与专项故障导出保存；当前仓库只保留当前有效结构。\n\n## 4. 修改与提交\n\n默认在当前 checkout 分支修改；没有明确需要时不创建临时分支。完成一组可独立验收的修改后再提交。若任务明确要求“不提交/不推送”，则以本地工作区/补丁作为交付，禁止覆盖用户指令。\n\n## 5. 验收分层\n\n仓库自动验证至少覆盖 Typecheck → Unit → Acceptance → Build → API E2E → Desktop E2E。真实模型/真实数据库/真实项目必须由本地验收证明；无 API Key 时真实模型步骤必须明确 skipped，不能伪装成功。\n\n`verify-local.mjs` 的 latest 报告只保留最新一次；测试通过不等于业务完成，也不等于系统规则治理完成。\n\n## 6. 规则修改的工程要求\n\n任何 `QUALITY_EXECUTION.md` Rule ID 变更必须在同一变更集同步：机器 Registry、消费者、参数源、页面投影、回归测试和旧副本清理。不得只改文档或只改代码。\n',
    'server/src/modules/module-standards/system-workflow-rule.types.ts': "/** Compatibility re-export. Machine rule types are owned by server/shared/src. */\nexport * from '../../../shared/src/system-workflow-rule.types';\n",
}
